namespace Rmg.Core.Composition;

/// <summary>
///     What every choice a genre may speak of does, in a sentence or two, as the genre editor shows it under the choice
///     (<see cref="GenreChoice.Description" />): what the listener hears, and how its options lean. A choice of every part's
///     or every drum role's own, such as its instruments, takes its family's, by the part.
/// </summary>
public static class GenreChoiceDescriptions
{
    private static readonly Dictionary<string, string> Own = new()
    {
        ["tempo"] = "How fast the song plays, in beats a minute: the range a song's tempo is drawn from, and whether it leans to the slow end or the fast.",
        ["length"] = "How long the song plays: the range its form is stretched or cut to, and whether it leans to the short end or the long.",
        ["darkness"] = "How dark the songs' mood is, from the brightest to the darkest: the darker, the likelier the darker of the options it allows, a minor or a Phrygian mode over a major or a Lydian one.",
        ["intensity"] = "How intense the songs' mood is, from the calmest to the fiercest: the fiercer, the likelier the fiercer of the options it allows.",
        ["meter"] = "How many beats a bar has and how they group: 4/4 for most songs, 3/4 and 6/8 for a waltz or a lilt, the odd meters for the wilder.",
        ["feel"] = "The song's feel: straight 8ths and 16ths for most songs, or triplets, quintuplets and groupings such as the tresillo's 3+3+2 for the wilder.",
        ["feelChances"] = "How often a song swings its 8ths or 16ths, and how often a section's drums go to half time, heavier, or double time, more urgent.",
        ["feelValues"] = "How hard a swinging song swings, from lightly to a full triplet shuffle, and how fast a tempo may still swing its 16ths rather than its 8ths.",
        ["scale"] = "The scale the song is in, which colours every chord and line: major and minor for most, the modes for a folk, jazz or modal sound, the rarer ones exotic.",
        ["chordShape"] = "What the chords are built of: plain triads, power chords for rock, sevenths and ninths for jazz and soul, sus and quartal chords for an open, modern sound.",
        ["arpeggio"] = "Whether the chords and the rhythm part play their notes together or one by one, up, down, back and forth, as a harp or a synth's arpeggiator does, or picked with an alternating thumb, root and fifth on the beats and the fingers between, as a folk or a country guitarist does.",
        ["colour"] = "A tone a part breaking its chord lays on it, its own, the band's chord as it was: a ninth's or a major seventh's shimmer, a flat second's or a sharp fourth's menace, as a metal guitar's clean arpeggio rings over the riff; or two of the key's tones held over every chord, sweet or menacing, rubbing against them.",
        ["rootDegree"] = "Which chords the progressions lean to, by their degree above the section's home: rock's ♭VII and ♭VI in a minor or Mixolydian key, a metal riff's ♭VI. Above the middle a chord is likelier, below rarer.",
        ["strictness"] = "How closely a progression keeps to its rules: above the middle, every chord on its place as a blues keeps its twelve bars at any conventionality; below it, roots wandering more.",
        ["cadenceDegree"] = "Which chord leads home at a progression's end, by its degree: a classical V, or a modal band's ♭II, ♭VI or ♭VII. Above the middle a chord is likelier, below rarer.",
        ["cadenceRaise"] = "How often a minor key's cadence raises its seventh, its chord on the fifth turned major to lead home as classical music does; a modal band's never.",
        ["sectionHome"] = "The key a section's chords move around: the song's tonic, its relative key (a minor song's major third, as a chorus lifts into it), or its fourth or fifth. A dark genre stays on its minor tonic.",
        ["rootMotion"] = "How the chords move from one to the next: by fifths for jazz's ii–V, by fourths for rock's IV–I, by steps and thirds for pop's loops. Above the middle a move is likelier, below rarer.",
        ["chordScales"] = "Chords that borrow notes from outside the key: a dominant leading into a chord, a chord from the parallel minor or major, the blues' every chord a dominant, a chord on a scale of its own, a mode's colour, or a chromatic mediant, iii or vi turned major.",
        ["harmonicRhythm"] = "How often the chords change: two a bar for busy harmony, one a bar for most songs, one every two bars for a loop or a groove.",
        ["vamp"] = "How often a section sits on one chord the whole way through, as a funk band or a techno track does.",
        ["turnaround"] = "How often a section's last bar leads back to its start through V, or ii–V, as jazz and the blues do.",
        ["passingKind"] = "How a passing chord leads into the next: by the next chord's dominant, the next chord sliding into it from a semitone above or below, the tritone substitute for its dominant, or a half-diminished chord a semitone below it between roots a whole step apart.",
        ["passingChords"] = "How often a chord passes into the next through a chord between them, as the passing kind leads it, a jazz and soul colour.",
        ["planing"] = "How often a section slides its home chord's shape up and down by semitones, a modern, filmic colour, and how often its planed chords each take a mode of their own.",
        ["harmonyDevices"] = "Reharmonising a section when it comes back, a chromatic line moving inside a held chord, and a bass note held under a section's changing chords.",
        ["loop"] = "How often a section plays the song's first section's chords again, as a beat loops one progression for the whole track.",
        ["ownMode"] = "The mode a chord takes on its own root, where it takes one: Lydian, Mixolydian and Dorian, a note from the plain scales, melodic minor and Phrygian stranger; a planed chord's quality is its mode's.",
        ["lineScale"] = "The scale the melody's and the riff's passing notes take: the key's, the pentatonic and blues scales for rock and blues, the jazz and symmetric ones for an outside sound.",
        ["riffScale"] = "The scale the riff's passing notes and accents take where it differs from the melody's: chromatic and octatonic for a dissonant metal riff under a melodic lead.",
        ["ornaments"] = "How often a song's melody and counter-melody ornament their notes: a quick grace note before a note, a turn around a held one, a trill on a long one, as a flute or a fiddle does.",
        ["appoggiatura"] = "How often the melody's and the counter-melody's notes on a strong beat lean on a tension that the next note, on a weaker beat over the same chord, resolves by step to the chord's, as a singer leans into a word and falls to the chord; the songs' own now and then, never in the plainest.",
        ["tension"] = "How often the melody's and the counter-melody's notes on a strong beat land on a tension, a note of the scale outside the chord, its ninth, eleventh or thirteenth, or a mode's flat second, rather than on the chord's, as a synth over a heavy band holds a note against it; the songs never hold one, though their appoggiaturas lean on one and resolve it.",
        ["melodyRange"] = "How far the melody roams: narrow, as a chant or a hook, or wide, as a jazz tune.",
        ["bass"] = "How much the bass leads into a new chord, walking its notes towards it, from never to as a walking jazz bass.",
        ["alternatingBass"] = "How often a section's bass alternates the chord's root and its fifth on its strong beats while the chord lasts, the fifth below the root where it fits, as a country or a polka bass does; and how often it walks a boogie instead, climbing the chord's root, third, fifth, sixth and seventh and back, as a blues or a rock and roll bass does.",
        ["octaveBass"] = "How often a section's bass bounces between a note and its octave, as disco and funk basses do.",
        ["glide"] = "How often the song's bass slides from note to note, as an 808 or an acid line does.",
        ["bassLanding"] = "What the bass lands on when the chord changes: the root, steadiest, the third or the fifth, lighter, or wherever its figure takes it.",
        ["effects"] = "How often a song uses each gentle effect: a vibrato on held notes, a chorus shimmer, a swell into held chords, bent notes, and a darker tone on some parts, a mellow guitar or a dull bass, darker still in the quiet sections, a worn tape's wow, the pitch drifting by a few cents, some parts held a little off, a guitar's pinch harmonics, a held note squealing now and then, and a riff's whammy dive into a louder section.",
        ["gateParts"] = "The parts a trance gate may chop: the pad, the chords or the rhythm part holding their chords, or the riff, its held chord stuttering in 16ths.",
        ["articulation"] = "How the notes are played: a line's steps slurred together, a piano's chords rolled from the bottom up, the chords struck short as stabs, a broken chord's notes let ring.",
        ["levels"] = "How loud each part plays against the others: above the middle louder, below quieter, as a beat's drums lead it or a dub's bass does.",
        ["rests"] = "How often each part sits out a section: above the middle the oftener, as a dub's drums and bass drop out.",
        ["sung"] = "How often a section's melody is sung in lines, resting halfway through its phrase as well as at its end, and in 8ths, no note of it shorter, as a voice phrases; below the middle its phrases run on and run in 16ths, as a played tune's or a rapper's do.",
        ["voice"] = "How often a verse leaves its melody out, the room a rapper's voice takes over the beat.",
        ["grooveHold"] = "How steady the groove stays from section to section: above the middle the backbeat holds to 2 and 4 and the patterns barely move.",
        ["pins"] = "How often each part keeps one figure every bar, unchanging, as a four-on-the-floor kick or a reggae skank does.",
        ["ghosts"] = "How often a section's snare plays ghost notes, soft 16ths off the beat between its backbeats, the likelier next to one, as a funk or soul drummer does; the same 16ths in every bar of the section.",
        ["rudiments"] = "How often a song's snare flams, a soft stroke just before a note, on its beats in a fill, as a rock or a marching drummer accents one; and drags, two, into its backbeat, as a jazz or a funk drummer does.",
        ["hatRolls"] = "How often a bar ends with the hi-hat rolling in 32nds or triplets, as trap does.",
        ["pocket"] = "How the parts sit around the beat: above the middle laid back, the backbeat and the lead behind it, below tight on the grid.",
        ["fills"] = "How much the drums fill into a new section: above the middle oftener and longer, below seldom and short.",
        ["kickOut"] = "How often a line's fill is the kick dropping out instead, the hats, the snare and the bass playing on without it into the downbeat, as a dance track drops its kick for a beat or a bar before the next section.",
        ["drop"] = "How often the band builds to a louder section and drops out for the bar before it, as dance music does.",
        ["mutation"] = "How often a drum bar takes an edit that the bars after it keep, a hit moved, dropped, doubled or ratcheted, two 8ths swapped, the kick and snare traded, so that the groove strays further as a section goes on, as a programmed break evolves.",
        ["drumSoloFeet"] = "What a drum solo's feet keep time with while the hands solo: the groove's kick, the hi-hat's pedal on 2 and 4 as a jazz drummer's, a double kick in 16ths as a metal drummer's, or the bossa's kick.",
        ["sticking"] = "The stickings a drum solo's runs are played in: single and double strokes, paradiddles, six-stroke rolls, hands and foot in triplets, or a cascade down the toms, the right hand moving round the toms and the left on the snare.",
        ["dropKind"] = "How a drop takes the bar before it: the band silent, or the band playing on through the whole mix closing to muffled and bursting open on the drop's downbeat.",
        ["mixFilter"] = "How often the whole mix is filtered, every part muffled together: a song opening up from muffled over its intro, a section's last bar or two closing before the next bursts in open, and the song closing as it ends.",
        ["breakdown"] = "How often a bridge, or a section of a free form, is a heavy band's breakdown: the drums in half time, the kick striking with the riff, the riff chugging on its lowest note, the melody, the counter-melody and the pad laying out.",
        ["riffIntro"] = "How often a song opens on its riff alone, the band coming in part by part after it, as a riff-driven band's song does, in place of the genre's other intro.",
        ["stopTime"] = "How often a section's first phrase plays in stop time, the band hitting once a bar under the melody, as the blues and rock do.",
        ["ensembleHits"] = "How often a section's last bar before a louder one is struck in ensemble hits, the band hitting with the kick and resting between, as funk and horn bands do.",
        ["push"] = "How often a section plays its chord changes an 8th early, an anticipation that pushes the groove forward.",
        ["keyChanges"] = "How often the last chorus lifts to a higher key, a section plays in a key of its own, or the key changes anywhere at all.",
        ["hook"] = "How often a chorus, or any other section, is built on a short repeating melodic hook.",
        ["riff"] = "How often a section's riff plays in power chords, how often its guitars and picked bass chug, their repeated notes palm-muted, and how often it drones, its weak notes on an open string and its melody leaping an octave or more above it, as a black metal, a folk metal or a djent riff does; and how often it is a figure, its first bar's notes kept over the chords that follow where they fit, rather than placed anew over each.",
        ["solos"] = "How often a section that comes back is played as a solo instead, and how often a solo trades with the drums, turn by turn, the band laying out for theirs, and how often a solo is played by two parts together a third apart, a twin-guitar break.",
        ["soloists"] = "Which part takes the solos: the solo part, a lead such as a sax or a guitar, or another part, even the drums.",
        ["intro"] = "How the song starts: the whole band at once, a count-in, or the parts coming in one by one.",
        ["ending"] = "How the song ends: a short final hit, a ringing chord, a sudden stop, a fade, its parts dropping out one by one to the drums, or left open.",
        ["strongEffect"] = "The one bold effect a song may put on a part: an echo, a tremolo, a sweep from side to side, the pads and bass pumping to the kick, a synth's filter wobbling, squelching or opening, or a trance gate chopping a pad.",
        ["echo"] = "How an echo repeats: after a dotted 8th, a quarter or an 8th, dying away over several repeats, or a dotted 8th once, almost as loud, a cascade, its repeats filling broken chords in 8ths into a run of 16ths.",
        ["insertion"] = "An effect one part plays through, the one a song may have: a wah on a guitar or a clavinet comping, as funk's, or a phaser swirling held chords, as disco's strings or a synth pad.",
        ["room"] = "The room the reverb is: a small room for a dry, close band, a hall for a big, open space, a plate for the bright, smooth studio reverb of the 80s; the player's own where a genre names none.",
        ["pan"] = "How far each part sits from the middle: above the middle wider, below closer to the centre.",
        ["formChances"] = "How often a song takes one of the classic song forms, with verses and choruses, rather than a form of its own.",
        ["form"] = "Which classic forms a song may take: verse and chorus, with a pre-chorus or a bridge, or AABA's verses and bridge.",
        ["sectionLength"] = "How many times a section plays its pattern over: once, twice or four times, a verse or a chorus the longer, a dance track's the longest.",
        ["phraseScheme"] = "How a section's phrase repeats its bars, as four, fitted to a phrase of three or of four and two: AAAA for a loop, AAAB with a different last bar, ABAB, or every bar different for the wildest.",
        ["texture"] = "How a section brings its parts in: all through, building up, thinning out, or one part alone.",
        ["dynamics"] = "How loud and busy the song is, how much its sections differ, how long the band swells into a louder section, from a beat to a whole phrase, and how evenly its parts are played, as a heavy band or a programmed beat strikes alike and a jazz band breathes.",
        ["phrases"] = "How long a section's chord pattern is before it repeats: 4 bars for most songs, 8 for a longer phrase, 12 for the blues, 16 for a tune.",
        ["phraseBars"] = "How many bars a section's phrase has: four for most songs; three, a folk tune's, its second bar left out; or four and two, its last two bars played again before the cadence arrives. For a section whose pattern is one phrase.",
        ["sectionChanges"] = "How often a section changes the song's tempo, by a jump or by a metric ratio, plays in a meter of its own, or cuts its last bar short, and how often a change of tempo is eased into over the bar before rather than taken at once.",
        ["alone"] = "Which part plays a section alone, where its texture leaves one: a clean guitar's arpeggio in a metal intro, a pad in an ambient piece, a piano in a ballad.",
        ["polymeter"] = "How often a section's riff, bass and kick run in a cycle of a different length across the bar, as djent and math rock do.",
        ["soloAnswers"] = "How often the solo part answers the melody in its gaps, as a guitarist fills between a singer's lines.",
        ["callAndResponse"] = "How often a verse calls and its band answers, as a blues or a soul band does: the melody singing the first half of every phrase and resting in the second, where the riff answers it.",
        ["lastRepeat"] = "How often the last chorus is played twice, and how often its first pass is a breakdown, built up from the voice alone, the drums next and the full band by its end.",
        ["doubling"] = "How often a line is doubled: in octaves by its own part, the melody harmonised by the counter-melody, now and then in three voices, the bass playing the riff with it, and, in a song with a twin, the sections its twin leads, the riff in single notes, busier, played as a soloist plays.",
        ["instrumentSwitches"] = "How often a section hands a part to another instrument, as a chorus's strings take over from a verse's piano.",
        ["space"] = "How much reverb each part has: above the middle wetter, as an ambient wash, below drier, as a funk band's room.",
        ["drumJob"] = "What the drums do: keep time, as a band's drums do, or mark the form now and then, as a calm piece's percussion does.",
        ["ghostNotes"] = "How many soft 16ths a ghosting snare plays around its backbeat: below the middle fewer, as a fast break wants, above it more.",
        ["marks"] = "How often drums marking the form strike, and how often they swell through a section's start, a roll growing to it and fading after: above the middle oftener.",
        ["register"] = "How high each part sits: at the lowest quarter an octave down, as a guitar tuned down, at the highest an octave up, as a bass singing high.",
        ["drumSounds"] = "How often each of a drum's own sounds plays as an accent and in fills: a metal china, a disco's open hi-hat off the beat.",
        ["drumStrokes"] = "How often each of a drum's own sounds is its steady stroke: the cross-stick of a ballad, a jazz drummer's hi-hat foot, a loud chorus's open hi-hat.",
        ["louderForms"] = "How often a louder section turns heavy, its clean guitars distorted, as a band kicks in the distortion for the chorus, and how often a quieter one turns calm, its distorted guitars acoustic or clean, one breaking the chords slowly and letting them ring, the others resting, the drums in half time.",
        ["harmonyInterval"] = "The interval a harmonised line plays apart from it: thirds and sixths, sweetest, fourths and fifths, open and old, or seconds and sevenths, the harshest.",
        ["kit"] = "The drum kit's sound: a standard or a room kit, a power kit for rock, electronic and TR-808 kits for dance and hip-hop, jazz and brush kits, or an orchestra's timpani.",
        ["parts"] = "Which parts play: the chance of each in a song, above 0 at an end where it may play.",
        ["drumSetup"] = "What kind of drums the song has: a drum kit, a kit with hand percussion, or hand percussion alone.",
        ["drumPieces"] = "Which drums and percussion the song may have, and how likely each is."
    };

    /// <summary>
    ///     A choice's description: its own, or for a part's or a drum role's choice its family's, by the part (Melody, Ground
    ///     (kick)); none for a choice that has neither, which a test finds.
    /// </summary>
    /// <param name="label">How the page shows the choice, which a family's description names the part by.</param>
    public static string Of(string name, string label) => Own.TryGetValue(name, out var own) ? own : name.Split('.') switch
    {
        ["instrument", _] => $"The instruments the {Lower(label)} part plays, and how likely each is.",
        ["rhythm", _] => $"How the {Lower(label)} plays its rhythm: how fast, how far off the beat, how fine its notes, how much weight its weaker beats get, how full and how repetitive. Above the middle more, below less.",
        ["feel", _] => $"The {Lower(label)}'s own feel over the song's: straight, or in triplets, quintuplets or groupings such as the tresillo's 3+3+2.",
        ["drumRole", _] => $"Which drums play the {Lower(label)} role in the groove, and how likely each is.",
        ["figure", _] => $"The figures the {Lower(label)} plays in a section in place of its own rhythm, each named by what it plays, and how likely each is, the louder the section the likelier.",
        _ => ""
    };

    private static string Lower(string label) => label.Length > 1 && char.IsUpper(label[0]) && !char.IsUpper(label[1]) ? char.ToLowerInvariant(label[0]) + label[1..] : label;
}
